    private const string SchedulesFileName = "scheduled-agent-runs.json";

    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)    public const string ExecutionsFileName = "scheduled-agent-executions.json";
    {
        WriteIndented = true
    };

    private static readonly SemaphoreSlim FileLock = new(1, 1)

    private async Task SaveExecutionsAsync(List<ScheduledAgentExecution> executions, CancellationToken cancellationToken)
    {
        var path = Path.Combine(environment.ContentRootPath, "Data", ExecutionsFileName);
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
        {
            Directory.CreateDirectory(directory);
        }

        await using var stream = File.Create(path);
        await JsonSerializer.SerializeAsync(stream, executions, JsonOptions, cancellationToken);
    }

    private async Task<List<ScheduledAgentExecution>> LoadExecutionsAsync(CancellationToken cancellationToken)
    {
        var path = Path.Combine(environment.ContentRootPath, "Data", ExecutionsFileName);
        if (!File.Exists(path))
        {
            return [];
        }

        await using var stream = File.OpenRead(path);
        return await JsonSerializer.DeserializeAsync<List<ScheduledAgentExecution>>(stream, JsonOptions, cancellationToken) ?? [];
    }

    private async Task<IReadOnlyList<ScheduledAgentExecution>> GetExecutionsForRunAsync(string scheduledRunId, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = (await LoadExecutionsAsync(cancellationToken))
                .Where(item => item.ScheduledRunId.Equals(scheduledRunId, StringComparison.OrdinalIgnoreCase));
            return executions
                .OrderBy(item => item.Name, StringComparer.OrdinalIgnoreCase)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    private async Task<IReadOnlyList<ScheduledAgentExecution>> GetExecutionsAsync(CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            return (await LoadExecutionsAsync(cancellationToken))
                .OrderBy(item => item.Name, StringComparer.OrdinalIgnoreCase)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }
    private async Task<ScheduledAgentExecution> CreateExecutionAsync(ScheduledAgentExecution execution, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(execution);

        var saved = await ValidateAndNormalizeAsync(execution, cancellationToken);
        saved.Id = Guid.NewGuid().ToString("N");
        saved.CreatedAtUtc = saved.CreatedAtUtc == default ? DateTime.UtcNow : saved.CreatedAtUtc;

        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var executions = await LoadExecutionsAsync(cancellationToken);
            executions.Add(saved);
            await SaveExecutionsAsync(executions, cancellationToken);
            return Clone(saved);
        }
        finally
        {
            FileLock.Release();
        }
    };

    public async Task<IReadOnlyList<ScheduledAgentRun>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            return (await LoadAsync(cancellationToken))
                .OrderBy(item => item.Name, StringComparer.OrdinalIgnoreCase)
                .Select(Clone)
                .ToArray();
        }
        finally
        {
            FileLock.Release();
        }
    }

    public async Task<IReadOnlyList<ScheduledAgentRun>> GetDueRunsAsync(DateTimeOffset nowUtc, CancellationToken cancellationToken = default)
    {
        await FileLock.WaitAsync(cancellationToken);
        try
        {
            var now = nowUtc.UtcDateTime;
            return (await LoadAsync(cancellationToken))
                .Where(item => item.Enabled
                    && !item.IsRunning
                    && GetEffectiveNextRunUtc(item).HasValue
                    && GetEffectiveNextRunUtc(item)!.Value <= now)
                .OrderBy(item => GetEffectiveNextRunUtc(item))
